package com.german_software_engineers.trainerappmodel;

import com.german_software_engineers.trainerappmodel.Enumerations.TrainingsTypes;
import com.german_software_engineers.trainerappmodel.Legacy.Schedule;
import com.german_software_engineers.trainerappmodel.Model.Model;
import com.german_software_engineers.trainerappmodel.Model.XMLParser;

import org.junit.Test;

import java.io.File;

import static org.junit.Assert.*;

public class TrainingsTypeRoundTripTest {

    @Test
    public void trainingsTypeIsStoredAndRestored() throws Exception {
        File file = File.createTempFile("DataFile", ".xml");

        Model writeModel = new Model();
        XMLParser writeParser = new XMLParser(writeModel);
        writeParser.setCurrentApplicationVersion("1902");

        Schedule schedule = new Schedule("MySchedule");
        // this is what the spinner (position 2 == "maximum strength") delivers
        schedule.setTrainingsType(TrainingsTypes.fromPosition(2));
        schedule.setRepetitions(10);
        schedule.setPauseTime(60);
        schedule.setSets(3);
        schedule.setSpeed(2);
        writeModel.addSchedule(schedule);

        assertTrue(writeParser.writeFile(file));

        Model readModel = new Model();
        XMLParser readParser = new XMLParser(readModel);
        assertTrue(readParser.parseFile(file));

        Schedule restored = readModel.getSchedule("MySchedule");
        assertEquals(TrainingsTypes.maximum_strength, restored.getTrainingsType());
        assertEquals("maximum strength", restored.getTrainingsType().displayName());

        file.delete();
    }

    @Test
    public void missingTrainingsTypeDoesNotBreakParsing() {
        assertEquals(TrainingsTypes.invalid, TrainingsTypes.fromName(""));
        assertEquals(TrainingsTypes.invalid, TrainingsTypes.fromName("nonsense"));
        assertEquals(TrainingsTypes.invalid, TrainingsTypes.fromPosition(-1));
        assertEquals(TrainingsTypes.invalid, TrainingsTypes.fromPosition(99));
        assertEquals(TrainingsTypes.strength_endurance, TrainingsTypes.fromPosition(0));
        assertEquals(TrainingsTypes.pyramid_training, TrainingsTypes.fromPosition(3));
        assertEquals(TrainingsTypes.invalid, new Schedule("x").getTrainingsType());
    }
}
